update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p001","body":"عشق زخم عارضی تھا\nپر یہ داغ جاودانی ہے\n\nشاید میں تمہیں کھو چکا ہوں\nشاید یہی اپنی کہانی ہے"},{"slug":"tum-p002","body":"دھواں ہی دھواں ہے آشیانے میں\nایک عمر لگی تمہیں بھلانے میں\n\nمت چھیڑو ذکر ، خاموش رہو\nزخم جلتا ہے سننے سنانے میں\n\nکچھ آوارگی میں ، کچھ بے چارگی میں\nکچھ بھلانے میں ، کچھ بتانے میں\n\nآشنائی سے تشنگی تک\nہنسانے سے رلانے میں\n\nخزاں بھی کہتی ہے اے بہار\nسرد تنہائی ہے ہر  دہانے میں\n\nآج کی بات آج نہیں احمد\nکل کی پھر کبھی انجانے میں"},{"slug":"tum-p003","body":"آج سے کئی برسوں بعد جب\nراہ گزرتے اچانک تم کہیں ملے اگر\nتو یہ سوچتا ہوں میں یونہی اکثر\nکہ کس قدر وقت بدل چکا ہوگا\nتم آگے بڑھ چکے ہو میں سنبھل چکا ہوںگا\nیہ چاند شفق ستاروں کے مدار وہی ہونگے\nانھیں دیکھنے کا مگر انداز بدلا ہوگا\nناو اپنی حسرتوں کی کہیں تو پار لگی ہوگی\nیا تو من  گلستاں ہوگا یا پھر کوئی صحرا ہوگا\n\nآج سے کئی برسوں بعد جب\nراہ گزرتے اچانک تم کہیں ملے اگر\n\nتو یہ سوچتا ہوں میں یونہی اکثر\nکہ کہیں یہ دل مردہ نہ ہو\nیا کوئی اس میں زندہ نہ ہو\nیا تو نہ صبح سویرے ہوں\nیہ بھی نہ شب اندھیرے ہوں\nیا کہ نہ کوئی پاس ہو\nیا کچھ بھی نہ راس ہو\n\nآج سے کئی برسوں بعد\nیہ سوچتا ہوں میں یونہی اکثر\nکہ ہو بس مجھے یہ میسر\nایک کاغذ ، قلم اور کوئی منزل\nکچھ خواب ، حسرت اور یہی دل\n\nپر پھر سوچتا ہوں میں یونہی اکثر\nآج سے کئی برسوں بعد\nراہ گزرتے تم کہیں ملے اگر۔۔۔۔۔"},{"slug":"tum-p004","body":"درر سُلگتا ہے اور اُگل جاتا ہے\nآدمی آدمی ہے سنبھل جاتا ہے\n\nیہ ہم تم ہیں جنھیں یہیں رہنا ہے\nشاہ کا کیا ہے، وہ تو محل جاتا ہے\n\nدل بھی عجیب ہے جس سے دُکھتا ہے\nاسی کے نام سے پھر بہل جاتا ہے\n\nآپ کی خاطر جیے دیتے ہیں\nوگرنہ جہاں تو نِگل جاتا ہے\n\nشوق کا حَوض بھی کچھ ایسا ہے\nایک نظر کیا دیکھیے اُبل جاتا ہے\n\nٹھیک اسی طرح دن نکلتا ہے، شام ڈھلتی ہے\nیہ بس انساں ہے احمدٗ جو بدل جاتا ہے"},{"slug":"tum-p005","body":"آپ کی یاد آتی رہی رات بھر\nدل جلاتی رہی رات بھر\n\nجذبوں کی بےلَوث معیشت پہ\nپستی چھاتی رہی رات بھر\n\nکسی کے پلٹے قدموں کی\nآواز آتی رہی رات بھر\n\nایک دھڑکن نے ساتھ دیا بس\nباقی دشمنی ذاتی رہی رات بھر\n\nدرد کے ابر گرجتے رہے\nخاموشی سرسراتی رہی رات بھر\n\nستارے ڈوبتے چلے گئے\nچاندنی اِتراتی رہی رات بھر\n\nبھلے دنوں کے سپنوں کی\nتمںا بھاتی رہی رات بھر\n\nوہ سکون سے سوتا رہا\nوہ خواب سجاتی رہی رات بھر\n\nدن فرصت نظر ہوا احمد\nرات جگاتی رہی رات بھر"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
